create extension if not exists pgcrypto;
create table if not exists organizations(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz default now());
create table if not exists users(id uuid primary key,organization_id uuid references organizations(id),email text not null,role text not null default 'member',created_at timestamptz default now());
create table if not exists clients(id uuid primary key default gen_random_uuid(),organization_id uuid references organizations(id),name text not null,company text,industry text,status text default 'prospect',created_at timestamptz default now());
create table if not exists leads(id uuid primary key default gen_random_uuid(),organization_id uuid references organizations(id),client_id uuid references clients(id),name text,email text,phone text,source text,stage text default 'new',score numeric default 0,metadata jsonb default '{}',created_at timestamptz default now());
create table if not exists projects(id uuid primary key default gen_random_uuid(),organization_id uuid references organizations(id),client_id uuid references clients(id),name text not null,status text default 'planning',due_at timestamptz,created_at timestamptz default now());
create table if not exists tasks(id uuid primary key default gen_random_uuid(),project_id uuid references projects(id),title text not null,status text default 'todo',priority text default 'normal',assigned_to uuid references users(id),due_at timestamptz,created_at timestamptz default now());
create table if not exists campaigns(id uuid primary key default gen_random_uuid(),client_id uuid references clients(id),name text not null,channel text,status text default 'draft',budget numeric default 0,metadata jsonb default '{}',created_at timestamptz default now());
create table if not exists content_items(id uuid primary key default gen_random_uuid(),client_id uuid references clients(id),campaign_id uuid references campaigns(id),title text,body text,channel text,status text default 'draft',scheduled_at timestamptz,created_at timestamptz default now());
create table if not exists agent_runs(id uuid primary key default gen_random_uuid(),organization_id uuid references organizations(id),agent text not null,goal text not null,status text default 'queued',input jsonb default '{}',output jsonb default '{}',created_at timestamptz default now(),completed_at timestamptz);
create table if not exists approvals(id uuid primary key default gen_random_uuid(),organization_id uuid references organizations(id),agent_run_id uuid references agent_runs(id),action text not null,payload jsonb default '{}',status text default 'pending',created_at timestamptz default now(),resolved_at timestamptz);
